import pandas as pd
import numpy as np

def calculate_net_acceleration_vector_length(df):
    df['net_acceleration_vector_length'] = np.sqrt(df['x']**2 + df['y']**2 + df['z']**2)
    return df['net_acceleration_vector_length']

def find_median_net_acceleration_vector_length(df, subject_id, activity_label):
    filtered_df = df[(df['subject_id'] == subject_id) & (df['activity_label'] == 'Ascending steps')]
    if filtered_df.empty:
        raise ValueError("No data found for user {} and activity 'Ascending steps'".format(subject_id))
    net_acceleration_vector_length = calculate_net_acceleration_vector_length(filtered_df)
    return net_acceleration_vector_length.median()

result = find_median_net_acceleration_vector_length(df, 20, 'Ascending steps')

import pandas as pd
import numpy as np
from scipy import stats

# Calculate cadence for each subject
def calculate_cadence(data):
    subjects = data['subject_id'].unique()
    cadences = []
    for subject in subjects:
        subject_data = data[data['subject_id'] == subject]
        timestamps = subject_data['timestamp']
        time_diffs = np.diff(timestamps)
        if len(time_diffs) > 0:
            cadence = 1 / np.mean(time_diffs)
            cadences.append(cadence)
        else:
            cadences.append(np.nan)
    return cadences

# Determine the gender of each subject
def determine_gender(data):
    try:
        subject_genders = pd.read_csv('subject_genders.csv')
        subject_genders = subject_genders.set_index('subject_id')
        genders = []
        for subject in data['subject_id'].unique():
            try:
                gender = subject_genders.loc[subject, 'gender']
                genders.append(gender)
            except KeyError:
                print(f"Error: Subject {subject} not found in subject_genders.csv")
                genders.append(None)
        return genders
    except FileNotFoundError:
        print("Error: subject_genders.csv not found")
        return [None] * len(data['subject_id'].unique())

# Compare cadence between female and male subjects
def compare_cadence(data, genders, cadences):
    female_cadences = [cadence for gender, cadence in zip(genders, cadences) if gender == 'Female' and not np.isnan(cadence)]
    male_cadences = [cadence for gender, cadence in zip(genders, cadences) if gender == 'Male' and not np.isnan(cadence)]

    # Perform a two-sample t-test to compare the means of the two groups
    try:
        t_stat, p_val = stats.ttest_ind(female_cadences, male_cadences)
    except ValueError:
        print("Error: Not enough data to perform t-test")
        return False

    # Print the results
    print(f'T-test statistic: {t_stat}')
    print(f'p-value: {p_val}')

    # Interpret the results
    if p_val < 0.05:
        print("Reject the null hypothesis: Female subjects have a significantly different cadence than male subjects.")
        if np.mean(female_cadences) > np.mean(male_cadences):
            print("Female subjects have a higher cadence than male subjects.")
        else:
            print("Male subjects have a higher cadence than female subjects.")
    else:
        print("Fail to reject the null hypothesis: Female subjects do not have a significantly different cadence than male subjects.")

    return p_val < 0.05 and np.mean(female_cadences) > np.mean(male_cadences)

# Main function
def main():
    global result
    cadences = calculate_cadence(df)
    genders = determine_gender(df)
    result = compare_cadence(df, genders, cadences)

if __name__ == "__main__":
    main()

